(function(){"use strict";app.factory("docRecibidoService",function(t){const e="Compra/DocumentoRecibido/",n="Compra/Proveedor/";let i=t.get("mainService"),o={get:function(t){return i.getData("get",e+"Get/"+JSON.stringify(t),null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let n=JSON.parse(e.payload);return t.tipo&&"1"===t.tipo?n:(t.tipo&&t.tipo,n[0])}})},readFileTxt:function(t){return i.getDataFile(`${e}Read`,t,null,!0)},uploadXml:function(t,n){return i.getDataFile(`${e}UploadXml/?json=${JSON.stringify(t)}`,n,null,!0)},checkExistenceXml:function(t){return i.getData("post",`${e}CheckExistenceXml/?claveAcceso=${t}`,null,!0)},post:function(t){return i.getData("post",`${e}Post`,{data:t},!0).then(t=>t)},putXml:function(t){return i.getData("put",`${e}Put/${t}`,null,!0)},putXmlManual:function(t,n){return i.getDataFile(`${e}${t}/${n}`,file,null,!0)},delete:function(t){return i.getData("delete",`${e}${t}`,null,!0)},getId:function(t){return i.getData("get",`${e}GetId/${t}`,null,!0)},migrate:function(t){return i.getData("put",`${e}Migrate`,{data:t},!0)},getProveedor:function(t){return i.getData("get",`${n}${JSON.stringify(t)}`,null,!0).then(e=>{if("0"===e.code)return e;if("1"===e.code){let n=JSON.parse(e.payload);if(1===t.tipo)return n;if(2===t.tipo)return{tiposIdentificacion:n[0],tiposProveedor:n[1],tiposEntidad:n[2],contribuyentes:n[3],tiemposCredito:n[4],ciudades:n[5]}}})}};return o})})(window.angular);